import type {
  FilterDataStructure,
  FilterForm,
  FilterValue,
} from 'models/Filters';

import { FilterConfig } from '../types';

const calculateDefaultZone = (
  filterData: FilterDataStructure,
  // eslint-disable-next-line @typescript-eslint/no-unused-vars -- FilterDefaultCalculator requires this parameter
  _: FilterForm,
): FilterValue => {
  const defaultZone = filterData.zones?.default?.value;
  const defaultCountries = filterData.country?.values?.[defaultZone as string];
  const countriesByZone = filterData.country?.values;

  if (defaultCountries && defaultCountries.length > 0) {
    return defaultZone ?? null;
  }

  for (const [zone, countries] of Object.entries(countriesByZone ?? {})) {
    if (Array.isArray(countries) && countries.length > 0) {
      return zone;
    }
  }

  return null;
};

/**
 * Finds a zone that exists in filter options and contains the given country
 * (skips ABI so regional zones win when the same country appears globally).
 */
const findValidZoneForCountry = (
  filterData: FilterDataStructure,
  country: FilterValue,
  zoneOptions: Array<{ value: unknown }>,
): string | null => {
  if (!country || country === 'ABI') return null;

  const countryValues = filterData.country?.values;
  if (!countryValues || Array.isArray(countryValues)) return null;

  const validZoneSet = new Set(
    zoneOptions
      .map((opt) => {
        const value = opt?.value;
        return typeof value === 'string' || typeof value === 'number'
          ? String(value)
          : '';
      })
      .filter(Boolean),
  );

  for (const [zoneKey, countries] of Object.entries(countryValues)) {
    if (zoneKey === 'ABI') continue;
    if (!validZoneSet.has(zoneKey)) continue;
    if (
      Array.isArray(countries) &&
      countries.some(
        (countryOption) => String(countryOption?.value) === String(country),
      )
    ) {
      return zoneKey;
    }
  }

  return null;
};

export const zonesFilterConfig: FilterConfig = {
  key: 'zone',
  order: 30,
  isCommon: true,
  calculator: calculateDefaultZone,
  dependentDefaultCascadingCalculator: (filterData, currentValues) => {
    const zoneOptions = filterData.zones?.values || [];
    if (!zoneOptions.length) return null;

    const currentZone = currentValues.zone;
    if (
      currentZone != null &&
      currentZone !== '' &&
      zoneOptions.some((opt) => String(opt.value) === String(currentZone))
    ) {
      return currentZone;
    }

    const derivedZone = findValidZoneForCountry(
      filterData,
      currentValues.country,
      zoneOptions,
    );
    if (derivedZone != null) return derivedZone;

    return calculateDefaultZone(filterData, currentValues);
  },
  validator: (filterData, value) => {
    const options = filterData.zones?.values || [];
    return options.some((opt) => opt.value === value);
  },
  contextualValidator: (dataFilters, _parent, zoneValue) => {
    const values = dataFilters.country?.values;
    if (!values || Array.isArray(values) || zoneValue == null) {
      return false;
    }
    const countries = values[String(zoneValue)];
    return Array.isArray(countries) && countries.length > 0;
  },
  dependencies: [
    'country',
    'brands',
    'sub_brands',
    'brands_abi',
    'brands_comp',
    'brand_filter_groupings',
    'audience_targeting_brands',
    'audience_targeting_brands_comp',
    'scopes',
    'sub_scopes',
    'global_brands',
    'growth_levers',
  ],
  metadata: {
    displayName: 'Zones',
    description: 'Geographic zones filter',
  },
};
